import{_ as o,a as e}from"./chunks/qr-testflight.C3Fq-bxs.js";import{_ as t,o as n,c as r,a5 as s}from"./chunks/framework.BYXPg_yw.js";const u=JSON.parse('{"title":"Downloads","description":"","frontmatter":{"layout":"doc","title":"Downloads"},"headers":[],"relativePath":"manual/downloads/index.md","filePath":"manual/downloads/index.md","lastUpdated":1792759058000}'),l={name:"manual/downloads/index.md"};function d(i,a,p,h,c,b){return n(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h1><p>Every RBQ download in one place — URDF (robot description) files, the <strong>RBQ Controller</strong> operator app, and the CAD · manual · software bundle, all reachable from a single page.</p><p>These are the <strong>nightly</strong> docs, so the app cards here carry the nightly build. The stable apps are on the stable docs&#39; <a href="https://rainbowrobotics.github.io/RBQ/manual/downloads/" target="_blank" rel="noreferrer">Downloads</a> page; run stable on robots you operate in the field. For how the two differ, see <a href="/RBQ/nightly/software/release-note/#channels">Stable and nightly</a>.</p><p>On a phone or tablet, scan a card&#39;s QR code with the camera to open its store page.</p><div class="rbq-download-grid"><a class="rbq-download-card" href="https://github.com/RainbowRobotics/RBQ/tree/main/resources/urdf" target="_blank" rel="noopener"><div class="rbq-download-icon" aria-hidden="true">📦</div><h3>URDF</h3><p>Robot description files for simulation and research. Hosted on GitHub.</p><span class="rbq-download-cta">Open on GitHub →</span></a><a class="rbq-download-card" href="https://play.google.com/store/apps/details?id=com.rainbowrobotics.rbq.nightly" target="_blank" rel="noopener"><div class="rbq-download-icon" aria-hidden="true">🌙</div><h3>RBQ Nightly (Android)</h3><p>The nightly build as a separate app, updated every night. It installs next to the stable app — run stable on robots you operate in the field.</p><img class="rbq-download-qr" src="'+o+'" alt="QR code for RBQ Nightly on Google Play" width="132" height="132"><span class="rbq-download-cta">Get it on Google Play →</span></a><a class="rbq-download-card" href="https://testflight.apple.com/join/9zRr7xC1" target="_blank" rel="noopener"><div class="rbq-download-icon" aria-hidden="true">🌙</div><h3>RBQ Controller beta (TestFlight)</h3><p>The nightly build for iPhone and iPad. Install Apple’s TestFlight app first, then join from this link. It replaces the App Store version on that device.</p><img class="rbq-download-qr" src="'+e+'" alt="QR code for the RBQ Controller TestFlight beta" width="132" height="132"><span class="rbq-download-cta">Join on TestFlight →</span></a><a class="rbq-download-card" href="https://github.com/RainbowRobotics/RBQ/releases/download/nightly/rbq-controller-x86_64.AppImage" target="_blank" rel="noopener" download><div class="rbq-download-icon" aria-hidden="true">🌙</div><h3>RBQ Nightly (Linux · Steam Deck)</h3><p>The nightly build of the desktop AppImage, rebuilt every night. It installs next to the stable app as a separate <strong>RBQ-nightly</strong> app — run stable on robots you operate in the field.</p><span class="rbq-download-cta">Download AppImage →</span></a><a class="rbq-download-card" href="/RBQ/nightly/manual/gui/software-update"><div class="rbq-download-icon" aria-hidden="true">🤖</div><h3>Robot software</h3><p>The software installed on the robot is not downloaded here. Each robot takes the package built for its own Ubuntu version and processor, and the app picks it: <strong>Maintenance → Software update</strong>.</p><span class="rbq-download-cta">Read Software update →</span></a><a class="rbq-download-card" href="https://rainbowco-my.sharepoint.com/:f:/g/personal/rbq_support_rainbow-robotics_com/IgCaa2vihZjyTKHTiEmmjzRsAbbKACHMA2OwCHlrDyH4y7w" target="_blank" rel="noopener"><div class="rbq-download-icon" aria-hidden="true">📐</div><h3>CAD · Manuals · Software · Sheet Stickers</h3><p>3D CAD models, manual PDFs, software bundles, and sheet stickers. Shared SharePoint folder.</p><span class="rbq-download-cta">Open SharePoint folder →</span></a></div>',5)])])}const f=t(l,[["render",d]]);export{u as __pageData,f as default};
